        "text": "每场战斗一次，当此模型被选择射击时，可使用此能力。若使用，直到阶段结束前，其「双生暴雨」武器的伤害特性为 3 且具有 **[针对步兵 5+]** 和 **[毁灭伤害]** 能力。",
