        "id": "unique-indomitable-strength-of-will",
        "name": "不屈意志",
        "text": "当此模型领导一个单位时，每当你花费一个战斗专注代币使该单位执行敏捷机动时，掷一次 D6：于 3+ 时，你获得 1 个战斗专注代币。",
